def transform(grid):
    h, w = len(grid), len(grid[0])

    # A solid nonzero row or column is the divider between two patterns.
    for r in range(h):
        if grid[r][0] != 0 and all(v == grid[r][0] for v in grid[r]):
            n = min(r, h - r - 1)
            return [
                [2 if grid[i][c] != 0 and grid[r + 1 + i][c] != 0 else 0
                 for c in range(w)]
                for i in range(n)
            ]

    for c in range(w):
        if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h)):
            n = min(c, w - c - 1)
            return [
                [2 if grid[r][i] != 0 and grid[r][c + 1 + i] != 0 else 0
                 for i in range(n)]
                for r in range(h)
            ]

    return [[0 for _ in row] for row in grid]
